window.AUTH=window.AUTH||{};window.AUTH["17-1678"]={"d":"17-1678","id":"2019/17-1678","n":"Hernandez v. Mesa","briefs":[{"k":"petitioner","label":"Brief of petitioners Jesus C. Hernández, et al.","date":"2019-08-02","url":"https://www.supremecourt.gov/DocketPDF/17/17-1678/111061/20190802111907651_17-1678%20ts%20PDFA.pdf","side":"pet","n":57},{"k":"respondent","label":"Brief of respondent Jesus Mesa, Jr.","date":"2019-09-23","url":"https://www.supremecourt.gov/DocketPDF/17/17-1678/116667/20190923131104744_Response%20Brief.pdf","side":"res","n":45},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-09-30","url":"https://www.supremecourt.gov/DocketPDF/17/17-1678/117525/20190930171236675_17-1678bsacUnitedStates.pdf","side":"us","n":70},{"k":"reply","label":"Reply of petitioners Jesus C. Hernández, et al.","date":"2019-10-23","url":"https://www.supremecourt.gov/DocketPDF/17/17-1678/119902/20191023085321619_Hernandez%20II%20--%20Reply%20Brief.pdf","side":"pet","n":49}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/589US1PP_Web.pdf#page=134","tr":true,"items":[{"t":"case","label":"Al Shimari v. CACI Premier Tech., Inc.","cite":"758 F.3d 516","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/758/516/","by":{"0":"32"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr.","cite":"135 S. Ct. 1378","y":2015,"id":"2014/14-15","sc":1,"by":{"0":"16","3":"22"},"q":[{"src":"brief","b":3,"text":"[t]he ability to sue to enjoin unconstitutional actions by state and federal officers is the creation of courts of equity, and reflects a long history of judicial review of illegal executive action, tracing back to England.","cite":"135 S. Ct. 1378, 1384"}]},{"t":"case","label":"Barr v. Matteo","cite":"360 U.S. 564","y":1959,"id":"1958/350","sc":1,"by":{"0":"16"}},{"t":"case","label":"Bartlett ex rel. Neuman v. Bowen","cite":"816 F.2d 695","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/816/695/","by":{"0":"42"}},{"t":"case","label":"Bates v. Clark","cite":"95 U.S. 204","y":1877,"id":"scdb/1877-066","sc":1,"by":{"0":"14"},"q":[{"src":"brief","b":0,"text":"[seeing] nothing . . . to prevent the marshal from being sued in the State court, in trespass for his own tort, in levying [the writ] upon the property of a man against whom the writ did not run, and on property which was not liable to it.","cite":"95 U.S. 204"}]},{"t":"case","label":"Belknap v. Schild","cite":"161 U.S. 10","y":1896,"id":"scdb/1895-108","sc":1,"by":{"0":"14"}},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"by":{"0":"7, 17"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of the Fed. Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"by":{"0":"passim","1":"passim","2":"1, 2, 8, 10, 12, 13","3":"1, 17, 23"},"q":[{"src":"brief","b":0,"text":"in the rare case where such a remedy was indispensable for vindicating constitutional rights.","cite":"403 U.S. 388"},{"src":"brief","b":0,"text":"the judiciary has a particular responsibility to assure the vindication of constitutional interests such as those embraced by the Fourth Amendment.","cite":"403 U.S. at 407"},{"src":"brief","b":2,"text":"rel[ied] largely on earlier decisions implying private damages actions into federal statutes.","cite":"403 U.S. at 397"},{"src":"brief","b":3,"text":"vindicate social policies which, by virtue of their inclusion in the Constitution, are aimed predominantly at restraining the Government as an instrument of the popular will.","cite":"403 U.S. at 404"},{"src":"argument","who":"Mr. Vladeck","text":"Chief Justice, and may it please the Court: When this case was first argued to this Court two years ago, counsel for Respondent and counsel for the United States were both asked whether Petitioners would have a Bivens remedy if Sergio Hernandez had been standing on U.S. soil when he was shot and killed by Respondent."},{"src":"argument","who":"Justice Ginsburg","text":"Suppose -- suppose there were no 1983, and a state officer had done exactly what the Bureau of Narcotics agents did in Bivens. Would there be an action against the state officer?"},{"src":"argument","who":"Mr. Vladeck","text":"And, actually, I think it's worth in this context reminding the Court of the government's position in Bivens. The government's position in Bivens itself was not that the federal courts should not be recognizing these remedies in any context."}]},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"by":{"0":"32","1":"14","3":"4, 20"},"q":[{"src":"argument","who":"Mr. Vladeck","text":"Is that a categorical on/off switch at the border, or are there reasons to actually think the Fourth Amendment question is more complicated in the context in which you have cross-border episodes, especially after Boumediene?"},{"src":"argument","who":"Mr. Ortega","text":"It would require an extension of Boumediene to a foreign country where the U.S. maintains no jurisdiction whatsoever, whether de facto or actual."}]},{"t":"case","label":"Bowen v. Mich. Acad. of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"the ‘serious constitutional question’ that would arise if a federal statute were construed to deny any judicial forum for a colorable constitutional claim","cite":"476 U.S. 667, 681 n.12"}]},{"t":"case","label":"Browder v. City of Albuquerque","cite":"787 F.3d 1076","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/787/1076/","by":{"0":"42"}},{"t":"case","label":"Carlson v. Green","cite":"446 U.S. 14","y":1980,"id":"1979/78-1261","sc":1,"by":{"0":"20","1":"6, 12","2":"11","3":"1, 11"},"q":[{"src":"argument","who":"Mr. Vladeck","text":"But, to -- to wind the clock forward, which I think is, of course, the -- the task for the Court today, I think it's worth stressing that, of the nine cases this Court has decided since Carlson, which the government points out at page 11 of its amicus brief, where this Court has had the opportunity to recognize a Bivens remedy and has chosen not to do so, none of those involved a claim that an individual federal law enforcement officer was acting ultra vires."},{"src":"argument","who":"Mr. Vladeck","text":"And so, to us, the questions blend together because it helps to drive home why this case is not like the nine cases this Court has had since Carlson --"}]},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"by":{"0":"39"}},{"t":"case","label":"Claflin v. Houseman","cite":"93 U.S. 130","y":1876,"id":"scdb/1876-027","sc":1,"by":{"0":"13"}},{"t":"case","label":"Corr. Servs. Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"by":{"0":"passim","1":"7, 8, 11, 25","2":"10, 11, 12, 13","3":"1, 5, 18"},"q":[{"src":"brief","b":0,"text":"presumably not even be repudiated by Congress.","cite":"534 U.S. at 75"},{"src":"brief","b":2,"text":"recognized for the first time an implied private action for damages against federal officers alleged to have violated a citizen’s constitutional rights.","cite":"534 U.S. 61, 66"},{"src":"brief","b":2,"text":"retreated from [its] previous willingness to imply a cause of action where Congress has not provided one.","cite":"534 U.S. at 67 n.3"},{"src":"brief","b":3,"text":"the core deterrence purpose of Bivens,","cite":"534 U.S. at 71"},{"src":"opinion","who":"Justice Thomas, concurring","text":"implied private action[s] for damages against federal offcers alleged to have violated a citizen's constitutional rights.","cite":"534 U. S., at 66"},{"src":"opinion","who":"Justice Thomas, concurring","text":"retreated from [its] previous willingness to imply a cause of action where Congress has not provided one.","cite":"534 U. S., at 67, n. 3"}]},{"t":"case","label":"Davis v. Passman","cite":"442 U.S. 228","y":1979,"id":"1978/78-5072","sc":1,"by":{"0":"23","1":"6, 25","2":"11"}},{"t":"case","label":"De La Paz v. Coy","cite":"786 F.3d 367","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/786/367/","by":{"0":"28"}},{"t":"case","label":"Def. Distrib. v. U.S. Dep’t of State","cite":"838 F.3d 451","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/838/451/","by":{"0":"30"},"q":[{"src":"brief","b":0,"text":"the Executive’s mere incantation of . . . ‘foreign affairs’ interests do not suffice to override constitutional rights.","cite":"838 F.3d 451, 474"}]},{"t":"case","label":"Delgado v. Zaragoza","cite":"267 F. Supp. 3d 892","y":2016,"court":"W.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/267/892/","by":{"0":"19","3":"18"},"q":[{"src":"brief","b":0,"text":"Texas state law explicitly provides that, under specified conditions, an individual may bring an action for personal injury damages in Texas although the wrongful act causing the injury took place in a foreign country.","cite":"267 F. Supp. 3d 892, 898"},{"src":"brief","b":3,"text":"Texas state law explicitly provides that, under specified conditions, an individual may bring an action for personal injury damages in Texas although the wrongful act causing the injury took place in a foreign country.","cite":"267 F. Supp. 3d 892, 898"}]},{"t":"case","label":"Dow Chem. Co. v. Castro Alfaro","cite":"786 S.W.2d 674","y":1990,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/786/674/","by":{"0":"19"}},{"t":"case","label":"Erie R.R. Co. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"by":{"0":"14, 17","2":"13","3":"21, 22"},"q":[{"src":"argument","who":"Mr. Wall","text":"And that was perfectly fine under federal common law up until Erie. And it was perfectly fine under state, statutory, and common law right up to the Westfall Act."}]},{"t":"case","label":"Felker v. Turpin","cite":"518 U.S. 651","y":1996,"id":"1995/95-8836","sc":1,"by":{"0":"41"}},{"t":"case","label":"Graham v. Connor","cite":"490 U.S. 386","y":1989,"id":"1988/87-6571","sc":1,"by":{"0":"24","1":"13","2":"4"}},{"t":"case","label":"Gutierrez de Martinez v. Lamagno","cite":"515 U.S. 417","y":1995,"id":"1994/94-167","sc":1,"by":{"0":"19","2":"30"},"q":[{"src":"brief","b":2,"text":"scope-of-employment certification[s] [are] reviewable in court,","cite":"515 U.S. 417, 420"}]},{"t":"case","label":"Haig v. Agee","cite":"453 U.S. 280","y":1981,"id":"1980/80-83","sc":1,"by":{"0":"29","2":"17"},"q":[{"src":"brief","b":0,"text":"the United States government is always responsible to foreign sovereigns when federal officials injure foreign citizens on foreign soil. These are often delicate diplomatic matters, and, as such, they ‘are rarely proper subjects for judicial intervention.’","cite":"453 U.S. 280, 292"},{"src":"brief","b":2,"text":"[m]atters intimately related to foreign policy and national security are rarely proper subjects for judicial intervention.","cite":"453 U.S. 280, 292"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"matters relating `to the conduct of foreign relations . . . are so exclusively entrusted to the political branches of government as to be largely immune from judicial inquiry or interference.'","cite":"453 U. S. 280, 292"}]},{"t":"case","label":"Harper v. Va. Dep’t of Taxation","cite":"509 U.S. 86","y":1993,"id":"1992/91-794","sc":1,"by":{"0":"15"}},{"t":"case","label":"Hernandez v. Mesa","cite":"137 S. Ct. 291","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./137/291/","sc":1,"by":{"0":"6"}},{"t":"case","label":"Hernandez v. Mesa (“Hernández I”)","cite":"137 S. Ct. 2003","y":2017,"id":"2016/15-118","sc":1,"by":{"0":"passim","1":"10, 13, 26","2":"2, 3, 5, 6"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"precedents, old and new, make clear that concerns of national security and foreign relations do not warrant abdication of the judicial role.","cite":"561 U.S. 1, 34"}]},{"t":"case","label":"Hui v. Castaneda","cite":"559 U.S. 799","y":2010,"id":"2009/08-1529","sc":1,"by":{"0":"20"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"the exclusive remedy for most claims against Government employees arising out of their offcial conduct.","cite":"559 U. S. 799, 806"}]},{"t":"case","label":"Kiobel v. Royal Dutch Petroleum Co.","cite":"569 U.S. 108","y":2012,"id":"2011/10-1491","sc":1,"by":{"0":"32","1":"18, 19","2":"26, 27, 28","3":"10, 14"},"q":[{"src":"brief","b":0,"text":"touch and concern the territory of the United States . . . with sufficient force to displace the presumption.","cite":"569 U.S. 108, 124–25"},{"src":"brief","b":2,"text":"United States law governs domestically but does not rule the world.","cite":"569 U.S. 108, 115"},{"src":"brief","b":2,"text":"helps ensure that the Judiciary does not erroneously adopt an interpretation of U.S. law that carries foreign policy consequences not clearly intended by the political branches.","cite":"569 U.S. at 116"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"ensure that the Judiciary does not erroneously adopt an interpretation of U. S. law that carries foreign policy consequences not clearly intended by the political branches.","cite":"569 U. S. 108, 116"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"the question is not what Congress has done but instead what courts may do.","cite":"569 U. S., at 116"},{"src":"argument","who":"Mr. Vladeck","text":"But even if this Court, nevertheless, believes that it's appropriate to map on that presumption, I actually think Kiobel helps us more than it hurts us, because, in Kiobel, this Court said there will still be cases in which the -- the underlying conduct, the gravamen of the plaintiff's complaint, involves activity that touches and concerns U.S. soil with sufficient force to displace the presumption against extraterritoriality."},{"src":"argument","who":"Mr. Vladeck","text":"But RJR Nabisco reinforces, it does not distinguish Kiobel in its suggestion that the presumption against extraterritoriality -- Mr. Chief Justice -- can be displaced when the underlying conduct touches and concerns U.S. territory with sufficient force to displace the presumption."}]},{"t":"case","label":"Kisela v. Hughes","cite":"138 S. Ct. 1148","y":2018,"id":"2017/17-467","sc":1,"by":{"0":"24"}},{"t":"case","label":"Lanuza v. Love","cite":"899 F.3d 1019","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/899/1019/","by":{"0":"28"}},{"t":"case","label":"Larson v. Domestic & Foreign Commerce Corp.","cite":"337 U.S. 682","y":1949,"id":"scdb/1948-106","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"the principle that an agent is liable for his own torts is an ancient one and applies even to certain acts of public officers or public instrumentalities.","cite":"337 U.S. 682, 686–87"}]},{"t":"case","label":"Manhattan Cmty. Access Corp. v. Halleck","cite":"139 S. Ct. 1921","y":2019,"id":"2018/17-1702","sc":1,"by":{"0":"4"}},{"t":"case","label":"Meshal v. Higgenbotham","cite":"804 F.3d 417","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/804/417/","by":{"0":"22","2":"24, 28","3":"10"},"q":[{"src":"brief","b":2,"text":"But the statute exempts U.S. officials, a point that President George H.W. Bush stressed when signing the legislation.","cite":"804 F.3d 417, 430"},{"src":"brief","b":2,"text":"grossly anomalous * * * to apply Bivens extraterritorially when [courts] would not apply an identical statutory cause of action for constitutional torts extraterritorially.","cite":"804 F.3d at 430"},{"src":"brief","b":3,"text":"‘Congress has deliberately decided not to fashion a cause of action’ for aliens injured abroad by federal officials.","cite":"804 F.3d 417, 430"},{"src":"argument","who":"Mr. Wall","text":"I don't have much to add to what Justice Kavanaugh said in Meshal in the D.C. Circuit. If there were a statute and it were the same as 1983 for federal officers, I don't take anybody to be disputing that, absent some clear indication in the language, that it wouldn't pick up an entry across the border."}]},{"t":"case","label":"Minneci v. Pollard","cite":"565 U.S. 118","y":2012,"id":"2011/10-1104","sc":1,"by":{"0":"1, 41","1":"8","2":"11","3":"1"}},{"t":"case","label":"Morrison v. Nat’l Austl. Bank","cite":"561 U.S. 247","y":2010,"id":"2009/08-1191","sc":1,"by":{"0":"31","1":"19, 20","2":"27","3":"13"},"q":[{"src":"brief","b":1,"text":"[t]his disregard of the presumption against extraterritoriality has occurred over many decades in many courts of appeals and has produced a collection of tests for divining congressional intent that are complex in formulation and unpredictable in application.","cite":"561 U.S. 247, 130"},{"src":"brief","b":2,"text":"[w]hen a statute gives no of State has not made a payment to petitioners (through Mexico) under that statute. clear indication of an extraterritorial application, it has none.","cite":"561 U.S. 247, 255"}]},{"t":"case","label":"Mullenix v. Luna","cite":"136 S. Ct. 305","y":2015,"id":"2015/14-1143","sc":1,"by":{"0":"24"}},{"t":"case","label":"Pearson v. Callahan","cite":"555 U.S. 223","y":2011,"id":"2008/07-751","sc":1,"by":{"0":"24"}},{"t":"case","label":"Poindexter v. Greenhow","cite":"114 U.S. 270","y":1885,"id":"scdb/1884-212","sc":1,"by":{"0":"15"}},{"t":"case","label":"RJR Nabisco, Inc. v. European Cmty.","cite":"136 S. Ct. 2090","y":2016,"id":"2015/15-138","sc":1,"by":{"0":"31","2":"27, 28, 29","3":"13"},"q":[{"src":"brief","b":0,"text":"avoid[s] the international discord that can result when U.S. law is applied to conduct in foreign countries.","cite":"136 S. Ct. 2090, 2100"},{"src":"argument","who":"Justice Ginsburg","text":"-- before you finish, can you address one decision that the government seems to put a lot of stock -- stock in, and that is RJR -- RS -- what is it -- R -- is it RJR Nabisco?"},{"src":"argument","who":"Mr. Vladeck","text":"But RJR Nabisco reinforces, it does not distinguish Kiobel in its suggestion that the presumption against extraterritoriality -- Mr. Chief Justice -- can be displaced when the underlying conduct touches and concerns U.S. territory with sufficient force to displace the presumption."}]},{"t":"case","label":"Rodriguez v. Swartz","cite":"899 F.3d 719","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/899/719/","by":{"0":"passim","1":"4, 20, 24, 27","2":"14","3":"6, 17"},"q":[{"src":"brief","b":0,"text":"the only [foreign] policy interest that the United States has put forward—maintaining dialogue with the Mexican government—shows that our government wants to reduce the number of crossborder shootings.","cite":"899 F.3d at 747"},{"src":"brief","b":0,"text":"[a] criminal charge is the government’s remedy, not the victim’s.","cite":"899 F.3d at 742"},{"src":"opinion","who":"Justice Thomas, concurring","text":"concurrently with whatever diplomacy may also be addressing them.","cite":"899 F. 3d 719, 747"},{"src":"opinion","who":"Justice Thomas, concurring","text":"It is inconceivable that . . . Congress [then] thought about (and deliberately excluded liability for) cross-border incidents involving federal offcials.","cite":"899 F. 3d, at 742"},{"src":"opinion","who":"Justice Thomas, concurring","text":"Domestic offcials were not at issue.","cite":"899 F. 3d 719, 743"}]},{"t":"case","label":"Sutton v. United States","cite":"819 F.2d 1289","y":1987,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/819/1289/","by":{"0":"22","3":"1"},"q":[{"src":"brief","b":0,"text":"in which a federal law enforcement officer uses excessive force, contrary to the Constitution or agency guidelines.","cite":"819 F.2d 1289, 1293"},{"src":"brief","b":3,"text":"classic Bivensstyle tort, in which a federal law enforcement officer uses excessive force, contrary to the Constitution or agency guidelines.","cite":"819 F.2d 1289, 1293"}]},{"t":"case","label":"Tun-Cos v. Perrotte","cite":"922 F.3d 514","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/922/514/","by":{"0":"2"}},{"t":"case","label":"Turkmen v. Ashcroft","cite":"2018 WL 4026734","y":2018,"court":"E.D.N.Y. Aug. 13","by":{"0":"26"}},{"t":"case","label":"United States v. Smith","cite":"499 U.S. 160","y":1991,"id":"1990/89-1646","sc":1,"by":{"0":"20"}},{"t":"case","label":"Vanderklok v. United States","cite":"868 F.3d 189","y":2017,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/868/189/","by":{"0":"2","1":"17, 18","2":"21, 31"},"q":[{"src":"brief","b":2,"text":"increas[ing] the likelihood that Border Patrol agents will ‘hesitate in making split second decisions.’","cite":"868 F.3d 189, 207"}]},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"by":{"0":"42","2":"32","3":"19"},"q":[{"src":"brief","b":3,"text":"any judicial forum for a colorable constitutional claim.","cite":"486 U.S. 592, 603"}]},{"t":"case","label":"Wheeldin v. Wheeler","cite":"373 U.S. 647","y":1963,"id":"1962/493","sc":1,"by":{"0":"15","3":"22"},"q":[{"src":"brief","b":0,"text":"[w]hen it comes to suits for damages for abuse of power, federal officials are usually governed by local law.","cite":"373 U.S. 647, 652"},{"src":"opinion","who":"Justice Thomas, concurring","text":"[I]t is not for us to fll any hiatus Congress has left in this area.","cite":"373 U. S., at 652"}]},{"t":"case","label":"Willingham v. Morgan","cite":"395 U.S. 402","y":1969,"id":"1968/228","sc":1,"by":{"0":"15"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"137 S. Ct. 1843","y":2017,"id":"2016/15-1358","sc":1,"by":{"0":"passim","1":"passim","2":"passim","3":"passim"},"q":[{"src":"brief","b":0,"text":"continued force, or even the necessity, of Bivens in the search-and-seizure context in which it arose.","cite":"137 S. Ct. at 1856"},{"src":"brief","b":0,"text":"talisman used to ward off inconvenient claims,","cite":"137 S. Ct. at 1862"},{"src":"brief","b":1,"text":"But the question you’re asking the Court to do is to shape a remedy . . . , a remedy that Congress has not provided.","cite":"137 S.Ct. 1843, 198"},{"src":"brief","b":1,"text":"damages against federal officials in order to remedy a constitutional violation.","cite":"137 S.Ct. 1843, 198"},{"src":"brief","b":2,"text":"notable change in the Court’s approach to recognizing implied causes of action, the Court has made clear that expanding the Bivens remedy is now a ‘disfavored’ judicial activity.","cite":"137 S. Ct. 1843, 1857"},{"src":"brief","b":2,"text":"consistently refused to extend Bivens to any new context or new category of defendants.","cite":"137 S. Ct. 1843, 1857"},{"src":"brief","b":3,"text":"[I]ndividual instances of . . . law enforcement overreach . . . are difficult to address except by way of damages actions after the fact.","cite":"137 S. Ct. at 1862"},{"src":"brief","b":3,"text":"a Bivens action is not ‘a proper vehicle for altering an entity’s policy.’","cite":"137 S. Ct. at 1860"}]},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"passim","2":"passim"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"passim","2":"passim","3":"19"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3"}},{"t":"law","label":"Pub. L. No. 93-253","url":"https://www.govinfo.gov/link/statute/88/50","by":{"0":"34"}},{"t":"reg","label":"8 C.F.R. § 287.8","url":"https://www.ecfr.gov/current/title-8/section-287.8","subs":["(a)(2)(ii)"],"by":{"0":"22, 29","3":"5"}},{"t":"case","label":"Abdoulaye v. Cimaglia","cite":"2018 U.S. Dist. LEXIS 56167","y":2018,"court":"S.D.N.Y. Mar. 30","by":{"1":"23, 24"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"by":{"1":"7","3":"21"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"During this `ancien regime,' . . . the Court assumed it to be a proper judicial function to `provide such remedies as are necessary to make effective' a statute's purpose . . . . Thus, as a routine matter with respect to statutes, the Court would imply causes of action not explicit in the statutory text itself.","cite":"532 U. S. 275, 287"}]},{"t":"case","label":"Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"by":{"1":"7","2":"8","3":"1, 5"}},{"t":"case","label":"Bureau of Land Management, Wilkie v. Robbins","cite":"551 U.S. 537","y":2007,"id":"2006/06-219","sc":1,"by":{"1":"27, 8, 21","2":"10, 11, 22, 29, 30, 33","3":"1"},"q":[{"src":"brief","b":1,"text":"paying particular heed, however, to any special factors counselling hesitation before authorizing a new kind of federal litigation.","cite":"551 U.S. 537, 550, 127"},{"src":"brief","b":2,"text":"freestanding damages remedy for a claimed constitutional violation * * * is not an absolute entitlement.","cite":"551 U.S. 537, 550"},{"src":"brief","b":2,"text":"is not an automatic entitlement no matter what other means there may be to vindicate a protected interest.","cite":"551 U.S. at 550"},{"src":"opinion","who":"Justice Thomas, concurring","text":"`Bivens is a relic of the heady days in which this Court assumed common-law powers to create causes of action.'","cite":"551 U. S. 537, 568"}]},{"t":"case","label":"Burwell v. Hobby Lobby Stores, Inc.","cite":"573 U.S. 682","y":2014,"id":"2013/13-354","sc":1,"by":{"1":"28, 29"}},{"t":"case","label":"Bush v. Lucas","cite":"462 U.S. 367","y":1983,"id":"1982/81-469","sc":1,"by":{"1":"7, 21","2":"11, 20, 22, 26","3":"1"},"q":[{"src":"brief","b":2,"text":"be augmented by the creation of a new judicial remedy.","cite":"462 U.S. at 388"}]},{"t":"case","label":"Cannon v. Univ. of Chi.","cite":"441 U.S. 677","y":1979,"id":"1978/77-926","sc":1,"by":{"1":"7"}},{"t":"case","label":"Chappell v. Wallace","cite":"462 U.S. 296","y":1983,"id":"1982/82-167","sc":1,"by":{"1":"7, 12","2":"11","3":"1"},"q":[{"src":"argument","who":"Mr. Wall","text":"-- under Chappell --"},{"src":"argument","who":"Mr. Wall","text":"And we know from Chappell that you weigh the special factors in aggregate. So the question just is, across all of these things, is there enough here to think that we ought to pause before we judicially imply a cause of action, and we ought to leave it to Congress."}]},{"t":"case","label":"Cuevas v. United States","cite":"2018 U.S. Dist. LEXIS 44915","y":2018,"court":"D. Colo. Mar. 19","by":{"1":"22"}},{"t":"case","label":"Doe v. Rumsfeld","cite":"683 F.3d 390","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/683/390/","by":{"1":"16"}},{"t":"case","label":"EEOC v. Arabian American Oil Co.","cite":"499 U.S. 244","y":1991,"id":"1990/89-1838","sc":1,"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"[t]he presumption ‘serves to protect against unintended clashes between our laws and those of other nations which could result in international discord.’","cite":"499 U.S. 244, 248, 111"}]},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"by":{"1":"8","2":"11","3":"1"}},{"t":"case","label":"Free v. Peikar","cite":"2018 U.S. Dist. LEXIS 25293","y":2018,"court":"E.D. Cal. Feb. 15","by":{"1":"23"}},{"t":"case","label":"Hernandez v. Mesa","cite":"885 F.3d 811","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/885/811/","by":{"1":"passim"},"q":[{"src":"brief","b":1,"text":"broke new ground by allowing suits that made constitutional claims against the federal government and its entities to proceed under a judicially recognized cause of action.","cite":"885 F.3d at 815"},{"src":"brief","b":1,"text":"unprovoked shooting of a civilian by a federal police officer is a prototypical excessive force claim, presents no ‘new context’ under Bivens.","cite":"885 F.3d at 816"}]},{"t":"case","label":"Hernandez v. Mesa","cite":"785 F.3d 117","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/785/117/","by":{"1":"1"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"was on Mexican soil at the time he was shot.","cite":"785 F. 3d 117, 119"}]},{"t":"case","label":"Hernandez v. United States","cite":"757 F.3d 249","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/757/249/","by":{"1":"27, 28"}},{"t":"case","label":"J.I. Case Co. v. Borak","cite":"377 U.S. 426","y":1964,"id":"1963/402","sc":1,"by":{"1":"6","2":"12"},"q":[{"src":"opinion","who":"Justice Thomas, concurring","text":"to be alert to provide such remedies as are necessary to make effective","cite":"377 U. S. 426, 433"},{"src":"argument","who":"Chief Justice Roberts","text":"We'll hear argument next in Case 17-1678, Hernandez versus Mesa. Mr. Vladeck. ORAL ARGUMENT OF STEPHEN I. VLADECK ON BEHALF OF THE PETITIONERS"}]},{"t":"case","label":"Leibelson v. Collins","cite":"2017 U.S. Dist. LEXIS 212026","y":2017,"court":"S.D. W. Va. Dec. 27","by":{"1":"22"}},{"t":"case","label":"Linlor v. Polson","cite":"263 F. Supp. 3d 613","y":2017,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/263/613/","by":{"1":"22, 23"}},{"t":"case","label":"Morgan v. Shivers","cite":"2018 U.S. Dist. LEXIS 14235","y":2018,"court":"S.D.N.Y. Jan. 29","by":{"1":"23"}},{"t":"case","label":"Nw. Austin Mun. Util. Dist. No. One v. Holder","cite":"557 U.S. 193","y":2009,"id":"2008/08-322","sc":1,"by":{"1":"28"}},{"t":"case","label":"Schweiker v. Chilicky","cite":"487 U.S. 412","y":1988,"id":"1987/86-1781","sc":1,"by":{"1":"8, 20","2":"passim","3":"1"},"q":[{"src":"brief","b":2,"text":"absence of statutory relief for a constitutional violation * * * does not by any means necessarily imply that courts should award money damages against the officers responsible for the violation.","cite":"487 U.S. at 421"},{"src":"brief","b":2,"text":"prospect of relief for injuries that must now go unredressed.","cite":"487 U.S. at 425"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"The absence of statutory relief for a constitutional violation . . . does not by any means necessarily imply that courts should award money damages against the offcers responsible for the violation.","cite":"487 U. S., at 421"}]},{"t":"case","label":"Shelby Cty. v. Holder","cite":"570 U.S. 529","y":2013,"id":"2012/12-96","sc":1,"by":{"1":"29"}},{"t":"case","label":"Turkmen v. Ashcroft","cite":"2018 U.S. Dist. LEXIS 137492","y":2018,"court":"E.D.N.Y.","by":{"1":"21"}},{"t":"case","label":"United States v. Delgado–Garcia","cite":"374 F.3d 1337","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/374/1337/","by":{"1":"16","2":"21"}},{"t":"case","label":"United States v. Stanley","cite":"483 U.S. 669","y":1987,"id":"1986/86-393","sc":1,"by":{"1":"7","2":"passim","3":"1"},"q":[{"src":"brief","b":2,"text":"it is irrelevant to a ‘special factors’ analysis whether the laws currently on the books afford [a plaintiff ] * * * an ‘adequate’ federal remedy for his injuries.","cite":"483 U.S. 669, 683"},{"src":"brief","b":2,"text":"congressionally uninvited intrusion into military affairs by the judiciary is inappropriate.","cite":"483 U.S. at 683"}]},{"t":"case","label":"United States v. Verdugo–Urquidez","cite":"494 U.S. 259","y":1990,"id":"1989/88-1353","sc":1,"by":{"1":"13, 26","2":"4"},"q":[{"src":"argument","who":"Mr. Vladeck","text":"So I think -- I think, Justice Ginsburg, that Verdugo certainly stands for the proposition that in that case there was no Fourth Amendment protection for a Mexican national whose home was searched by DEA agents operating in conjunction with the Mexican government."},{"src":"argument","who":"Mr. Vladeck","text":"There is some uncertainty about just how broadly this Court's decision in Verdugo-Urquidez, in which the Court said a Mexican national could not invoke the Fourth Amendment to challenge the search of his home -- the warrantless search of his home by a DEA officer, there's uncertainty about how far that sweeps."},{"src":"argument","who":"Mr. Ortega","text":"Assuming Verdugo did not foreclose that, then there would not be a difference."}]},{"t":"case","label":"Vega v. United States","cite":"881 F.3d 1146","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/881/1146/","by":{"1":"21"}},{"t":"const","label":"Article I, Section 9, Clause 2","clauses":[["habeas","Suspension Clause (Habeas Corpus)"]],"text":"The Privilege of the Writ of Habeas Corpus shall not be suspended, unless when in Cases of Rebellion or Invasion the public Safety may require it.","by":{"1":"14"}},{"t":"usc","label":"6 U.S.C. § 211","url":"https://www.law.cornell.edu/uscode/text/6/211","subs":["(c)","(e)(3)(B)"],"stext":{"head":"§211. Establishment of U.S. Customs and Border Protection; Commissioner, Deputy Commissioner, and operational offices","paras":[[0,"(a) In general"],[0,"There is established in the Department an agency to be known as U.S. Customs and Border Protection."],[0,"(b) Commissioner of U.S. Customs and Border Protection"],[0,"(1) In general"],[1,"There shall be at the head of U.S. Customs and Border Protection a Commissioner of U.S. Customs and Border Protection (in this section referred to as the \"Commissioner\")."],[0,"(2) Committee referral"],[1,"As an exercise of the rulemaking power of the Senate, any nomination for the Commissioner submitted to the Senate for confirmation, and referred to a committee, shall be referred to the Committee on Finance."],[0,"(c) Duties"],[0,"The Commissioner shall—"],[1,"(1) coordinate and integrate the security, trade facilitation, and trade enforcement functions of U.S. Customs and Border Protection;"],[1,"(2) ensure the interdiction of persons and goods illegally entering or exiting the United States;"],[1,"(3) facilitate and expedite the flow of legitimate travelers and trade;"],[1,"(4) direct and administer the commercial operations of U.S. Customs and Border Protection, and the enforcement of the customs and trade laws of the United States;"],[1,"(5) detect, respond to, and interdict terrorists, drug smugglers and traffickers, human smugglers and traffickers, and other persons who may undermine the security of the United States, in cases in which such persons are entering, or have recently entered, the United States;"],[1,"(6) safeguard the borders of the United States to protect against the entry of dangerous goods;"],[1,"(7) ensure the overall economic security of the United States is not diminished by efforts, activities, and programs aimed at securing the homeland;"],[1,"(8) in coordination with U.S. Immigration and Customs Enforcement and United States Citizenship and Immigration Services, enforce and administer all immigration laws, as such term is defined in paragraph (17) of section 1101(a) of title 8, including—"],[2,"(A) the inspection, processing, and admission of persons who seek to enter or depart the United States; and"],[2,"(B) the detection, interdiction, removal, departure from the United States, short-term detention, and transfer of persons unlawfully entering, or who have recently unlawfully entered, the United States;"],[1,"(9) develop and implement screening and targeting capabilities, including the screening, reviewing, identifying, and prioritizing of passengers and cargo across all international modes of transportation, both inbound and outbound;"],[1,"(10) in coordination with the Secretary, deploy technology to collect the data necessary for the Secretary to administer the biometric entry and exit data system pursuant to section 1365b of title 8;"],[1,"(11) enforce and administer the laws relating to agricultural import and entry inspection referred to in section 231 of this title;"],[1,"(12) in coordination with the Under Secretary for Management of the Department, ensure U.S. Customs and Border Protection complies with Federal law, the Federal Acquisition Regulation, and the Department's acquisition management directives for major acquisition programs of U.S. Customs and Border Protection;"],[1,"(13) ensure that the policies and regulations of U.S. Customs and Border Protection are consistent with the obligations of the United States pursuant to international agreements;"],[1,"(14) enforce and administer—"],[2,"(A) the Container Security Initiative program under section 205 of the Security and Accountability for Every Port Act of 2006 (6 U.S.C. 945); and"],[2,"(B) the Customs–Trade Partnership Against Terrorism program under subtitle B of title II of such Act (6 U.S.C. 961 et seq.);"],[1,"(15) conduct polygraph examinations in accordance with section 221(1) of this title;"],[1,"(16) establish the standard operating procedures described in subsection (k);"],[1,"(17) carry out the training required under subsection (l);"],[1,"(18) carry out section 218 of this title, relating to the issuance of Asia-Pacific Economic Cooperation Business Travel Cards; and"],[1,"(19) carry out other duties and powers prescribed by law or delegated by the Secretary."],[0,"(d) Deputy Commissioner"],[0,"There shall be in U.S. Customs and Border Protection a Deputy Commissioner who shall assist the Commissioner in the management of U.S. Customs and Border Protection."],[0,"(e) U.S. Border Patrol"],[0,"(1) In general"],[1,"There is established in U.S. Customs and Border Protection the U.S. Border Patrol."],[0,"(2) Chief"],[1,"There shall be at the head of the U.S. Border Patrol a Chief, who shall—"],[2,"(A) be at the level of Executive Assistant Commissioner within U.S. Customs and Border Protection; and"],[2,"(B) report to the Commissioner."],[0,"(3) Duties"],[1,"The U.S. Border Patrol shall—"],[2,"(A) serve as the law enforcement office of U.S. Customs and Border Protection with primary responsibility for interdicting persons attempting to illegally enter or exit the United States or goods being illegally imported into or exported from the United States at a place other than a designated port of entry;"],[2,"(B) deter and prevent the illegal entry of terrorists, terrorist weapons, persons, and contraband; and"],[2,"(C) carry out other duties and powers prescribed by the Commissioner."],[0,"(f) Air and Marine Operations"],[0,"(1) In general"],[1,"There is established in U.S. Customs and Border Protection an office known as Air and Marine Operations."],[0,"(2) Executive Assistant Commissioner"],[1,"There shall be at the head of Air and Marine Operations an Executive Assistant Commissioner, who shall report to the Commissioner."],[0,"(3) Duties"],[1,"Air and Marine Operations shall—"],[2,"(A) serve as the law enforcement office within U.S. Customs and Border Protection with primary responsibility to detect, interdict, and prevent acts of terrorism and the unlawful movement of people, illicit drugs, and other contraband across the borders of the United States in the air and maritime environment;"],[2,"(B) conduct joint aviation and marine operations with U.S. Immigration and Customs Enforcement;"],[2,"(C) conduct aviation and marine operations with international, Federal, State, and local law enforcement agencies, as appropriate;"],[2,"(D) administer the Air and Marine Operations Center established under paragraph (4); and"],[2,"(E) carry out other duties and powers prescribed by the Commissioner."],[0,"(4) Air and Marine Operations Center"],[0,"(A) In general"],[2,"There is established in Air and Marine Operations an Air and Marine Operations Center."],[0,"(B) Executive Director"],[2,"There shall be at the head of the Air and Marine Operations Center an Executive Director, who shall report to the Executive Assistant Commissioner of Air and Marine Operations."],[0,"(C) Duties"],[2,"The Air and Marine Operations Center shall—"],[3,"(i) manage the air and maritime domain awareness of the Department, as directed by the Secretary;"],[3,"(ii) monitor and coordinate the airspace for unmanned aerial systems operations of Air and Marine Operations in U.S. Customs and Border Protection;"],[3,"(iii) detect, identify, and coordinate a response to threats to national security in the air domain, in coordination with other appropriate agencies, as determined by the Executive Assistant Commissioner;"],[3,"(iv) provide aviation and marine support to other Federal, State, tribal, and local agencies; and"],[3,"(v) carry out other duties and powers prescribed by the Executive Assistant Commissioner."],[0,"(g) Office of Field Operations"],[0,"(1) In general"],[1,"There is established in U.S. Customs and Border Protection an Office of Field Operations."],[0,"(2) Executive Assistant Commissioner"],[1,"There shall be at the head of the Office of Field Operations an Executive Assistant Commissioner, who shall report to the Commissioner."],[0,"(3) Duties"],[1,"The Office of Field Operations shall coordinate the enforcement activities of U.S. Customs and Border Protection at United States air, land, and sea ports of entry to—"],[2,"(A) deter and prevent terrorists and terrorist weapons from entering the United States at such ports of entry;"],[2,"(B) conduct inspections at such ports of entry to safeguard the United States from terrorism and illegal entry of persons;"],[2,"(C) prevent illicit drugs, agricultural pests, and contraband from entering the United States;"],[2,"(D) in coordination with the Commissioner, facilitate and expedite the flow of legitimate travelers and trade;"],[2,"(E) administer the National Targeting Center established under paragraph (4);"],[2,"(F) coordinate with the Executive Assistant Commissioner for the Office of Trade with respect to the trade facilitation and trade enforcement activities of U.S. Customs and Border Protection; and"],[2,"(G) carry out other duties and powers prescribed by the Commissioner."],[0,"(4) National Targeting Center"],[0,"(A) In general"],[2,"There is established in the Office of Field Operations a National Targeting Center."],[0,"(B) Executive Director"],[2,"There shall be at the head of the National Targeting Center an Executive Director, who shall report to the Executive Assistant Commissioner of the Office of Field Operations."],[0,"(C) Duties"],[2,"The National Targeting Center shall—"],[3,"(i) serve as the primary forum for targeting operations within U.S. Customs and Border Protection to collect and analyze traveler and cargo information in advance of arrival in the United States to identify and address security risks and strengthen trade enforcement;"],[3,"(ii) identify, review, and target travelers and cargo for examination;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/6/211?type=usc&year=mostrecent&link-type=html"},"by":{"1":"17, 26","2":"21, 21"},"q":[{"src":"brief","b":2,"text":"deter[ring] and prevent[ing] the illegal entry of terrorists, terrorist weapons, persons, and contraband.","cite":"6 U.S.C. 211(e)(3)(B)"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"detect, respond to, and interdict terrorists, drug smugglers and traffckers, human smugglers and traffckers, and other persons who may undermine the security of the United States.","cite":"6 U. S. C. § 211(c)(5)"}]},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"by":{"1":"11","2":"9, 22, 23, 26","3":"9"},"q":[{"src":"brief","b":2,"text":"citizen[s] of the United States or other person[s] within the jurisdiction thereof.","cite":"42 U.S.C. 1983"}]},{"t":"case","label":"Bank Markazi v. Peterson","cite":"136 S. Ct. 1310","y":2016,"id":"2015/14-770","sc":1,"by":{"2":"17"},"q":[{"src":"brief","b":2,"text":"a domain in which the controlling role of the political branches is both necessary and proper.","cite":"136 S. Ct. 1310, 1328"}]},{"t":"case","label":"Blue Chip Stamps v. Manor Drug Stores","cite":"421 U.S. 723","y":1975,"id":"1974/74-124","sc":1,"by":{"2":"23"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"anomalous to impute . . . a judicially implied cause of action beyond the bounds [Congress has] delineated for [a] comparable express caus[e] of action.","cite":"421 U. S. 723, 736"}]},{"t":"case","label":"City of Milwaukee v. Illinois","cite":"451 U.S. 304","y":1981,"id":"1980/79-408","sc":1,"by":{"2":"13"}},{"t":"case","label":"Department of Navy v. Egan","cite":"484 U.S. 518","y":1988,"id":"1987/86-1552","sc":1,"by":{"2":"21"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"Thus, unless Congress specifcally has provided otherwise, courts traditionally have been reluctant to intrude upon the authority of the Executive in [these matters].","cite":"484 U. S. 518, 530"}]},{"t":"case","label":"Hartman v. Moore","cite":"547 U.S. 250","y":2006,"id":"2005/04-1495","sc":1,"by":{"2":"23"}},{"t":"case","label":"Imbler v. Pachtman","cite":"424 U.S. 409","y":1976,"id":"1975/74-5435","sc":1,"by":{"2":"33"}},{"t":"case","label":"Jamison v. Wiley","cite":"14 F.3d 222","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/14/222/","by":{"2":"31"}},{"t":"case","label":"Oetjen v. Central Leather Co.","cite":"246 U.S. 297","y":1918,"id":"scdb/1917-085","sc":1,"by":{"2":"17"},"q":[{"src":"brief","b":2,"text":"The conduct of the foreign relations of our Government is committed by the Constitution to the Executive and Legislative—‘the political’—Departments.","cite":"246 U.S. 297, 302"}]},{"t":"case","label":"Sanchez-Espinoza v. Reagan","cite":"770 F.2d 202","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/770/202/","by":{"2":"18","3":"4"},"q":[{"src":"brief","b":2,"text":"what [this] Court has called in another context ‘embarrassment of our government abroad’ through ‘multifarious pronouncements by various departments on one question.’","cite":"770 F.2d 202, 209"}]},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"by":{"2":"23","3":"11"},"q":[{"src":"brief","b":2,"text":"unwillingness to subject the United States to liabilities depending upon the laws of a foreign power,","cite":"542 U.S. 692, 707"},{"src":"brief","b":3,"text":"codified Congress’s ‘unwilling[ness] to subject the United States to liabilities depending upon the laws of a foreign power.’","cite":"542 U.S. 692, 707"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"is even more important . . . `to look for legislative guidance before exercising innovative authority over substantive law.'","cite":"542 U. S. 692, 726"},{"src":"opinion","who":"Justice Thomas, concurring","text":"Congress's `unwilling[ness] to subject the United States to liabilities depending upon the laws of a foreign power.'","cite":"542 U. S. 692, 707"}]},{"t":"case","label":"United States v. Cienfuegos","cite":"462 F.3d 1160","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/462/1160/","by":{"2":"31"}},{"t":"const","label":"Article II, Section 2","clauses":[["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"]],"text":"The President shall be Commander in Chief of the Army and Navy of the United States, and of the Militia of the several States, when called into the actual Service of the United States; he may require the Opinion, in writing, of the principal Officer in each of the executive Departments, upon any Subject relating to the Duties of their respective Offices, and he shall have Power to grant Reprieves and Pardons for Offences against the United States, except in Cases of Impeachment. He shall have Power, by and with the Advice and Consent of the Senate, to make Treaties, provided two thirds of the Senators present concur; and he shall nominate, and by and with the Advice and Consent of the Senate, shall appoint Ambassadors, other public Ministers and Consuls, Judges of the supreme Court, and all other Officers of the United States, whose Appointments are not herein otherwise provided for, and which shall be established by Law: but the Congress may by Law vest the Appointment of such inferior Officers, as they think proper, in the President alone, in the Courts of Law, or in the Heads of Departments. The President shall have Power to fill up all Vacancies that may happen during the Recess of the Senate, by granting Commissions which shall expire at the End of their next Session.","by":{"2":"17"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"2":"11"}},{"t":"usc","label":"28 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/28/1350","by":{"2":"3, 24"}},{"t":"usc","label":"28 U.S.C. § 2671","url":"https://www.law.cornell.edu/uscode/text/28/2671","by":{"2":"3"}},{"t":"usc","label":"28 U.S.C. § 2674","url":"https://www.law.cornell.edu/uscode/text/28/2674","by":{"2":"23"}},{"t":"usc","label":"28 U.S.C. § 2680","url":"https://www.law.cornell.edu/uscode/text/28/2680","subs":["(k)"],"stext":{"head":"§2680. Exceptions","paras":[[0,"The provisions of this chapter and section 1346(b) of this title shall not apply to—"],[0,"(a) Any claim based upon an act or omission of an employee of the Government, exercising due care, in the execution of a statute or regulation, whether or not such statute or regulation be valid, or based upon the exercise or performance or the failure to exercise or perform a discretionary function or duty on the part of a federal agency or an employee of the Government, whether or not the discretion involved be abused."],[0,"(b) Any claim arising out of the loss, miscarriage, or negligent transmission of letters or postal matter."],[0,"(c) Any claim arising in respect of the assessment or collection of any tax or customs duty, or the detention of any goods, merchandise, or other property by any officer of customs or excise or any other law enforcement officer, except that the provisions of this chapter and section 1346(b) of this title apply to any claim based on injury or loss of goods, merchandise, or other property, while in the possession of any officer of customs or excise or any other law enforcement officer, if—"],[1,"(1) the property was seized for the purpose of forfeiture under any provision of Federal law providing for the forfeiture of property other than as a sentence imposed upon conviction of a criminal offense;"],[1,"(2) the interest of the claimant was not forfeited;"],[1,"(3) the interest of the claimant was not remitted or mitigated (if the property was subject to forfeiture); and"],[1,"(4) the claimant was not convicted of a crime for which the interest of the claimant in the property was subject to forfeiture under a Federal criminal forfeiture law..1"],[0,"(d) Any claim for which a remedy is provided by chapter 309 or 311 of title 46 relating to claims or suits in admiralty against the United States."],[0,"(e) Any claim arising out of an act or omission of any employee of the Government in administering the provisions of sections 1–31 of Title 50, Appendix.2"],[0,"(f) Any claim for damages caused by the imposition or establishment of a quarantine by the United States."],[0,"[(g) Repealed. Sept. 26, 1950, ch. 1049, §13 (5), 64 Stat. 1043.]"],[0,"(h) Any claim arising out of assault, battery, false imprisonment, false arrest, malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights: Provided, That, with regard to acts or omissions of investigative or law enforcement officers of the United States Government, the provisions of this chapter and section 1346(b) of this title shall apply to any claim arising, on or after the date of the enactment of this proviso, out of assault, battery, false imprisonment, false arrest, abuse of process, or malicious prosecution. For the purpose of this subsection, \"investigative or law enforcement officer\" means any officer of the United States who is empowered by law to execute searches, to seize evidence, or to make arrests for violations of Federal law."],[0,"(i) Any claim for damages caused by the fiscal operations of the Treasury or by the regulation of the monetary system."],[0,"(j) Any claim arising out of the combatant activities of the military or naval forces, or the Coast Guard, during time of war."],[0,"(k) Any claim arising in a foreign country."],[0,"(l) Any claim arising from the activities of the Tennessee Valley Authority."],[0,"(m) Any claim arising from the activities of the Panama Canal Company."],[0,"(n) Any claim arising from the activities of a Federal land bank, a Federal intermediate credit bank, or a bank for cooperatives."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2680?type=usc&year=mostrecent&link-type=html"},"by":{"2":"23, 34"},"q":[{"src":"brief","b":2,"text":"[a]ny claim arising in a foreign country,","cite":"28 U.S.C. 2680(k)"},{"src":"opinion","who":"Justice Thomas, concurring","text":"claim[s] arising in a foreign country,","cite":"28 U. S. C. § 2680(k)"}]},{"t":"usc","label":"10 U.S.C. § 2734","url":"https://www.law.cornell.edu/uscode/text/10/2734","subs":["(a)","(a)(3)","(b)"],"stext":{"head":"§2734. Property loss; personal injury or death: incident to noncombat activities of the armed forces; foreign countries","paras":[[0,"(a) To promote and to maintain friendly relations through the prompt settlement of meritorious claims, the Secretary concerned, or an officer or employee designated by the Secretary, may appoint, under such regulations as the Secretary may prescribe, one or more claims commissions, each composed of one or more officers or employees or combination of officers or employees of the armed forces, to settle and pay in an amount not more than $100,000, a claim against the United States for—"],[1,"(1) damage to, or loss of, real property of any foreign country or of any political subdivision or inhabitant of a foreign country, including damage or loss incident to use and occupancy;"],[1,"(2) damage to, or loss of, personal property of any foreign country or of any political subdivision or inhabitant of a foreign country, including property bailed to the United States; or"],[1,"(3) personal injury to, or death of, any inhabitant of a foreign country;"],[0,"if the damage, loss, personal injury, or death occurs outside the United States, or the Commonwealths or possessions, and is caused by, or is otherwise incident to noncombat activities of, the armed forces under his jurisdiction, or is caused by a member thereof or by a civilian employee of the military department concerned or the Coast Guard, as the case may be. The claim of an insured, but not that of a subrogee, may be considered under this subsection. In this section, \"foreign country\" includes any place under the jurisdiction of the United States in a foreign country. An officer or employee may serve on a claims commission under the jurisdiction of another armed force only with the consent of the Secretary of his department, or his designee, but shall perform his duties under regulations of the department appointing the commission."],[0,"(b) A claim may be allowed under subsection (a) only if—"],[1,"(1) it is presented within two years after it accrues;"],[1,"(2) in the case of a national of a country at war with the United States, or of any ally of that country, the claimant is determined by the commission or by the local military commander to be friendly to the United States; and"],[1,"(3) it did not arise from action by an enemy or result directly or indirectly from an act of the armed forces of the United States in combat, except that a claim may be allowed if it arises from an accident or malfunction incident to the operation of an aircraft of the armed forces of the United States, including its airborne ordnance, indirectly related to combat, and occurring while preparing for, going to, or returning from a combat mission."],[0,"(c) The Secretary concerned may appoint any officer or employee under the jurisdiction of the Secretary to act as an approval authority for claims determined to be allowable under subsection (a) in an amount in excess of $10,000."],[0,"(d) If the Secretary concerned considers that a claim in excess of $100,000 is meritorious, and the claim otherwise is payable under this section, the Secretary may pay the claimant $100,000 and report any meritorious amount in excess of $100,000 to the Secretary of the Treasury for payment under section 1304 of title 31."],[0,"(e) Except as provided in subsection (d), no claim may be paid under this section unless the amount tendered is accepted by the claimant in full satisfaction."],[0,"(f) Upon the request of the department concerned, a claim arising in that department and covered by subsection (a) may be settled and paid by a commission appointed under subsection (a) and composed of officers of an armed force under the jurisdiction of another department."],[0,"(g) Payment of claims against the Coast Guard arising while it is operating as a service in the Department of Homeland Security shall be made out of the appropriation for the operating expenses of the Coast Guard."],[0,"(h) The Secretary of Defense may designate any claims commission appointed under subsection (a) to settle and pay, as provided in this section, claims for damage caused by a civilian employee of the Department of Defense other than an employee of a military department. Payments of claims under this subsection shall be made from appropriations as provided in section 2732 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/2734?type=usc&year=mostrecent&link-type=html"},"by":{"2":"25, 25, 25","3":"16"},"q":[{"src":"brief","b":3,"text":"caused by, or . . . otherwise incident to noncombat activities of, the armed forces.","cite":"10 U.S.C. § 2734(a)(3)"}]},{"t":"usc","label":"10 U.S.C. § 2734a","url":"https://www.law.cornell.edu/uscode/text/10/2734a","subs":["(a)"],"by":{"2":"25, 25"},"q":[{"src":"brief","b":2,"text":"an international agreement which provides for the settlement or adjudication and cost sharing of claims against the United States arising out of the acts or omissions of a member or civilian employee of an armed force of the United States.","cite":"10 U.S.C. 2734a(a)"}]},{"t":"law","label":"Pub. L. No. 102-256","url":"https://www.govinfo.gov/link/statute/106/73","by":{"2":"24"}},{"t":"usc","label":"28 U.S.C. § 2679","url":"https://www.law.cornell.edu/uscode/text/28/2679","subs":["(b)","(b)(2)(A)","(d)"],"stext":{"head":"§2679. Exclusiveness of remedy","paras":[[0,"(a) The authority of any federal agency to sue and be sued in its own name shall not be construed to authorize suits against such federal agency on claims which are cognizable under section 1346(b) of this title, and the remedies provided by this title in such cases shall be exclusive."],[0,"(b)(1) The remedy against the United States provided by sections 1346(b) and 2672 of this title for injury or loss of property, or personal injury or death arising or resulting from the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment is exclusive of any other civil action or proceeding for money damages by reason of the same subject matter against the employee whose act or omission gave rise to the claim or against the estate of such employee. Any other civil action or proceeding for money damages arising out of or relating to the same subject matter against the employee or the employee's estate is precluded without regard to when the act or omission occurred."],[0,"(2) Paragraph (1) does not extend or apply to a civil action against an employee of the Government—"],[1,"(A) which is brought for a violation of the Constitution of the United States, or"],[1,"(B) which is brought for a violation of a statute of the United States under which such action against an individual is otherwise authorized."],[0,"(c) The Attorney General shall defend any civil action or proceeding brought in any court against any employee of the Government or his estate for any such damage or injury. The employee against whom such civil action or proceeding is brought shall deliver within such time after date of service or knowledge of service as determined by the Attorney General, all process served upon him or an attested true copy thereof to his immediate superior or to whomever was designated by the head of his department to receive such papers and such person shall promptly furnish copies of the pleadings and process therein to the United States attorney for the district embracing the place wherein the proceeding is brought, to the Attorney General, and to the head of his employing Federal agency."],[0,"(d)(1) Upon certification by the Attorney General that the defendant employee was acting within the scope of his office or employment at the time of the incident out of which the claim arose, any civil action or proceeding commenced upon such claim in a United States district court shall be deemed an action against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant."],[0,"(2) Upon certification by the Attorney General that the defendant employee was acting within the scope of his office or employment at the time of the incident out of which the claim arose, any civil action or proceeding commenced upon such claim in a State court shall be removed without bond at any time before trial by the Attorney General to the district court of the United States for the district and division embracing the place in which the action or proceeding is pending. Such action or proceeding shall be deemed to be an action or proceeding brought against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant. This certification of the Attorney General shall conclusively establish scope of office or employment for purposes of removal."],[0,"(3) In the event that the Attorney General has refused to certify scope of office or employment under this section, the employee may at any time before trial petition the court to find and certify that the employee was acting within the scope of his office or employment. Upon such certification by the court, such action or proceeding shall be deemed to be an action or proceeding brought against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant. A copy of the petition shall be served upon the United States in accordance with the provisions of Rule 4(d)(4) 1 of the Federal Rules of Civil Procedure. In the event the petition is filed in a civil action or proceeding pending in a State court, the action or proceeding may be removed without bond by the Attorney General to the district court of the United States for the district and division embracing the place in which it is pending. If, in considering the petition, the district court determines that the employee was not acting within the scope of his office or employment, the action or proceeding shall be remanded to the State court."],[0,"(4) Upon certification, any action or proceeding subject to paragraph (1), (2), or (3) shall proceed in the same manner as any action against the United States filed pursuant to section 1346(b) of this title and shall be subject to the limitations and exceptions applicable to those actions."],[0,"(5) Whenever an action or proceeding in which the United States is substituted as the party defendant under this subsection is dismissed for failure first to present a claim pursuant to section 2675(a) of this title, such a claim shall be deemed to be timely presented under section 2401(b) of this title if—"],[1,"(A) the claim would have been timely had it been filed on the date the underlying civil action was commenced, and"],[1,"(B) the claim is presented to the appropriate Federal agency within 60 days after dismissal of the civil action."],[0,"(e) The Attorney General may compromise or settle any claim asserted in such civil action or proceeding in the manner provided in section 2677, and with the same effect."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2679?type=usc&year=mostrecent&link-type=html"},"by":{"2":"4, 30, 32, 33, 30"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"brought for a violation of the Constitution.","cite":"28 U. S. C. § 2679(b)(2)(A)"}]},{"t":"usc","label":"6 U.S.C. § 111","url":"https://www.law.cornell.edu/uscode/text/6/111","subs":["(b)(1)(A)","(b)(1)(E)"],"by":{"2":"21, 21"}},{"t":"usc","label":"8 U.S.C. § 1357","url":"https://www.law.cornell.edu/uscode/text/8/1357","subs":["(a)(5)"],"by":{"2":"31"}},{"t":"usc","label":"18 U.S.C. § 3663A","url":"https://www.law.cornell.edu/uscode/text/18/3663A","subs":["(a)"],"by":{"2":"31"}},{"t":"usc","label":"21 U.S.C. § 904","url":"https://www.law.cornell.edu/uscode/text/21/904","by":{"2":"25"}},{"t":"usc","label":"22 U.S.C. § 2669","url":"https://www.law.cornell.edu/uscode/text/22/2669","subs":["(b)"],"stext":{"head":"§2669. Printing and binding outside continental United States; settlement and payment of claims by foreign governments; employment of aliens; official functions and courtesies; purchase of uniforms; payment of tort claims; payment of assumed obligations in Germany; telecommunications services; security; special purpose passenger motor vehicles; pay obligations arising under international conventions or contracts; personal service contracts","paras":[[0,"The Secretary of State may use funds appropriated or otherwise available to the Secretary to—"],[1,"(a) provide for printing and binding outside the States of the United States and the District of Columbia without regard to section 501 of title 44;"],[1,"(b) for the purpose of promoting and maintaining friendly relations with foreign countries through the prompt settlement of certain claims, settle and pay any meritorious claim against the United States which is presented by a government of a foreign country for damage to or loss of real or personal property of, or personal injury to or death of, any national of such foreign country: Provided, That such claim is not cognizable under any other statute or international agreement of the United States and can be settled for not more than $15,000 or the foreign currency equivalent thereof;"],[1,"(c) employ individuals or organizations, by contract, for services abroad, and individuals employed by contract to perform such services shall not by virtue of such employment be considered to be employees of the United States Government for purposes of any law administered by the Office of Personnel Management (except that the Secretary may determine the applicability to such individuals of subsection (f) and of any other law administered by the Secretary concerning the employment of such individuals abroad); and such contracts are authorized to be negotiated, the terms of the contracts to be prescribed, and the work to be performed, where necessary, without regard to such statutory provisions as relate to the negotiation, making, and performance of contracts and performance of work in the United States;"],[1,"(d) provide for official functions and courtesies;"],[1,"(e) purchase uniforms;"],[1,"(f) pay tort claims, in the manner authorized in the first paragraph of section 2672, as amended, of title 28, when such claims arise in foreign countries in connection with Department of State operations abroad;"],[1,"(g) obtain services as authorized by section 3109 of title 5 at a rate not to exceed the maximum rate payable for GS–18 under section 5332 of such title 5;"],[1,"(h) directly procure goods and services in the United States or abroad, solely for use by United States Foreign Service posts abroad when the Secretary of State, in accordance with guidelines established in consultation with the Administrator of General Services, determines that use of the Federal Acquisition Service or otherwise applicable Federal goods and services acquisition authority would not meet emergency overseas security requirements determined necessary by the Secretary, taking into account overseas delivery, installation, maintenance, or replacement requirements, except that the authority granted by this paragraph shall cease to be effective when the amendment made by section 2711 of the Competition in Contracting Act of 1984 takes effect and thereafter procurement by the Secretary of State for the purposes described in this paragraph shall be in accordance with section 3304(a)(2) of title 41;"],[1,"(i) pay obligations assumed in Germany on or after June 5, 1945;"],[1,"(j) provide telecommunications services;"],[1,"(k) provide maximum physical security in Government-owned and leased properties and vehicles abroad;"],[1,"(l) purchase special purpose passenger motor vehicles without regard to any price limitation otherwise established by law;"],[1,"(m) pay obligations arising under international agreements, conventions, and binational contracts to the extent otherwise authorized by law;"],[1,"(n) exercise the authority provided in subsection (c), upon the request of the Secretary of Defense or the head of any other department or agency of the United States, to enter into personal service contracts with individuals to perform services in support of the Department of Defense or such other department or agency, as the case may be; and"],[1,"(o) make administrative corrections or adjustments to an employee's pay, allowances, or differentials, resulting from mistakes or retroactive personnel actions, as well as provide back pay and other categories of payments under section 5596 of title 5, as part of the settlement or compromise of administrative claims or grievances filed against the Department."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/2669?type=usc&year=mostrecent&link-type=html"},"by":{"2":"25","3":"16"},"q":[{"src":"brief","b":2,"text":"settle and pay any meritorious claim against the United States which is presented by a government of a foreign country for damage to or loss of real or personal property of, or personal injury to or death of, any national of such foreign country,","cite":"22 U.S.C. 2669(b)"}]},{"t":"usc","label":"22 U.S.C. § 2669-1","url":"https://www.law.cornell.edu/uscode/text/22/2669-1","by":{"2":"25"}},{"t":"reg","label":"8 C.F.R. § 287.10","url":"https://www.ecfr.gov/current/title-8/section-287.10","by":{"2":"31"}},{"t":"reg","label":"Exec. Order No. 13,732, § 2(b)(ii), 81 Fed. Reg. 44,486","url":"https://www.govinfo.gov/link/fr/81/44486","by":{"2":"24"}},{"t":"case","label":"Arar v. Ashcroft","cite":"585 F.3d 559","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/585/559/","by":{"3":"5"}},{"t":"case","label":"Baker v. Carr","cite":"369 U.S. 186","y":1962,"id":"1960/6","sc":1,"by":{"3":"5"},"q":[{"src":"brief","b":3,"text":"the potentiality of embarrassment from multifarious pronouncements by various departments on one question,","cite":"369 U.S. 186, 217"}]},{"t":"case","label":"Collins v. Virginia","cite":"138 S. Ct. 1663","y":2018,"id":"2017/16-1027","sc":1,"by":{"3":"21"}},{"t":"case","label":"El-Shifa Pharm. Indus. Co. v. United States","cite":"607 F.3d 836","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/607/836/","by":{"3":"4"}},{"t":"case","label":"Hamdi v. Rumsfeld","cite":"542 U.S. 507","y":2004,"id":"2003/03-6696","sc":1,"by":{"3":"4"}},{"t":"case","label":"Harbury v. Hayden","cite":"522 F.3d 413","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/522/413/","by":{"3":"15"},"q":[{"src":"brief","b":3,"text":"[t]he scope-of-employment test often is akin to asking whether the defendant merely was on duty or on the job when committing the alleged tort.","cite":"522 F.3d 413, 422 n.4"}]},{"t":"case","label":"Helvering v. Mitchell","cite":"303 U.S. 391","y":1938,"id":"scdb/1937-140","sc":1,"by":{"3":"7"},"q":[{"src":"brief","b":3,"text":"acquittal on a criminal charge is not a bar to a civil action . . . arising out of the same facts on which the criminal proceeding was based.","cite":"303 U.S. 391, 397"}]},{"t":"case","label":"Hinderlider v. La Plata River & Cherry Creek Ditch Co.","cite":"304 U.S. 92","y":1938,"id":"scdb/1937-042","sc":1,"by":{"3":"21"}},{"t":"case","label":"Jesner v. Arab Bank, PLC","cite":"138 S. Ct. 1386","y":2018,"id":"2017/16-499","sc":1,"by":{"3":"14, 21"}},{"t":"case","label":"Leal Garcia v. Texas","cite":"564 U.S. 940","y":2011,"id":"scdb/2010-085","sc":1,"by":{"3":"7"}},{"t":"case","label":"Rasul v. Myers","cite":"563 F.3d 527","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/563/527/","by":{"3":"4"}},{"t":"case","label":"Reid v. Covert","cite":"354 U.S. 1","y":1957,"id":"1955/701","sc":1,"by":{"3":"13"}},{"t":"case","label":"United States v. Spelar","cite":"338 U.S. 217","y":1949,"id":"scdb/1949-001","sc":1,"by":{"3":"11"}},{"t":"case","label":"Weinberger v. Salfi","cite":"422 U.S. 749","y":1975,"id":"1974/74-214","sc":1,"by":{"3":"19"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Clinton","cite":"566 U.S. 189","y":2012,"id":"2011/10-699","sc":1,"by":{"3":"4, 6"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(b)(1)"],"by":{"3":"11"}},{"t":"law","label":"Detainee Treatment Act (DTA), Pub. L. No. 109-148","url":"https://www.govinfo.gov/link/plaw/109/public/148","by":{"3":"12"}}]};